// ÚNICO lugar para editar o ID da conta do Instagram.
// Pegue em: Meta Graph API Explorer -> GET /me/accounts -> instagram_business_account
const IG_USER_ID = 'PASTE_YOUR_INSTAGRAM_USER_ID';

const items = [];

for (const item of $input.all()) {
  const card = item.json;

  let desc = {};
  try {
    const clean = card.desc.replace(/\\_/g, '_').replace(/\\"/g, '"');
    desc = JSON.parse(clean);
  } catch (e) {
    items.push({ json: {
      card_id: card.id, card_name: card.name, content_type: '', idea_description: '',
      caption: '', image_url: '', scheduled_time: '', expected_generation_date: '',
      ig_post_id: '', ig_user_id: IG_USER_ID,
      publish_error: 'Descrição do card não é JSON válido: ' + e.message,
      card_raw_desc: card.desc,
    }});
    continue;
  }

  const storedImageUrl = desc.image_url || '';
  const imageUrl = storedImageUrl && !/^https?:\/\//i.test(storedImageUrl)
    ? `https://${storedImageUrl}`
    : storedImageUrl;

  const base = {
    card_id: card.id,
    card_name: card.name,
    content_type: desc.content_type || '',
    idea_description: desc.idea_description || '',
    caption: desc.caption || '',
    image_url: imageUrl,
    scheduled_time: desc.scheduled_time || '',
    expected_generation_date: desc.expected_generation_date || '',
    ig_post_id: desc.ig_post_id || '',
    ig_user_id: IG_USER_ID,
    publish_error: '',
  };

  // Já publicado: não republica. Protege contra post duplicado se o card voltar
  // para Aprovado por engano ou se uma execução anterior morreu no meio.
  if (base.ig_post_id) continue;

  if (IG_USER_ID.startsWith('COLE_AQUI')) {
    base.publish_error = 'IG_USER_ID não configurado no node "Parse & validate".';
  } else if (!base.image_url) {
    base.publish_error = 'Card sem image_url — não passou pela geração de imagem.';
  } else if (!base.caption) {
    base.publish_error = 'Card sem caption.';
  } else if (!/^https:\/\/[^\s"]+\.jpe?g$/i.test(base.image_url)) {
    // O Instagram só aceita JPEG servido por URL pública https.
    base.publish_error = 'image_url precisa ser um .jpg público via https. Valor: ' + base.image_url;
  }

  items.push({ json: base });
}

return items;

// O node HTTP substitui item.json pela resposta — recupera o que veio antes.
// Referencia "Prep container" (e não "Parse & validate") de propósito: o IF
// anterior filtra itens, então só o node imediatamente antes do HTTP tem a
// mesma quantidade e ordem de itens. Casar por índice com um node de antes do
// filtro desalinharia os dados assim que um card fosse rejeitado.
const responses = $input.all();
const upstream = $('Prep container').all();
const items = [];

for (let i = 0; i < responses.length; i++) {
  const card = upstream[i].json;
  const res = responses[i].json;
  const body = res.body || {};

  if (res.statusCode === 200 && body.id) {
    items.push({ json: { ...card, creation_id: body.id } });
  } else {
    const err = body.error || {};
    const detalhe = err.message
      ? `${err.message} (code ${err.code}${err.error_subcode ? '/' + err.error_subcode : ''})`
      : JSON.stringify(body).slice(0, 300);
    items.push({ json: { ...card, publish_error: `Falha ao criar container: ${detalhe}` } });
  }
}

return items;

// Mesma regra do node anterior: o Wait é o último node antes do HTTP e passa
// os itens adiante sem alterar, então é ele que tem a lista alinhada.
const responses = $input.all();
const upstream = $('Aguardar processamento').all();
const items = [];

for (let i = 0; i < responses.length; i++) {
  const card = upstream[i].json;
  const res = responses[i].json;
  const body = res.body || {};

  if (res.statusCode === 200 && body.id) {
    items.push({ json: { ...card, ig_post_id: body.id, publish_error: '' } });
  } else {
    const err = body.error || {};
    const detalhe = err.message
      ? `${err.message} (code ${err.code}${err.error_subcode ? '/' + err.error_subcode : ''})`
      : JSON.stringify(body).slice(0, 300);
    items.push({ json: { ...card, publish_error: `Falha ao publicar: ${detalhe}` } });
  }
}

return items;
